import { useEffect, useState } from "react";
import { Desktop } from "@wxcc-desktop/sdk";

const WxccWhatsapp = ({ agentid: propAgentId }: { agentid?: string }) => {
  const [agentid, setAgentId] = useState<string | undefined>(propAgentId);

  useEffect(() => {
    if (!propAgentId) {
      try {
        const rawAgentId = (Desktop as any)?.agentStateInfo?.latestData?.agentId;
        if (rawAgentId) {
          console.log("Agent ID from SDK:", rawAgentId);
          setAgentId(rawAgentId);
        }
      } catch (err) {
        console.error("Error accessing agentId from SDK:", err);
      }
    }
  }, [propAgentId]);

  return (
    <div>
      <h2>WxCC WhatsApp Widget</h2>
      <p>🆔 ID de Agente: {agentid || "Cargando..."}</p>
    </div>
  );
};

export default WxccWhatsapp;
